<?php declare(strict_types=1);if(PHP_SAPI!=='cli')exit;require dirname(__DIR__).'/inc/db.php';require dirname(__DIR__).'/inc/order_service.php';$q=$pdo->query("SELECT id FROM order_headers WHERE payment_method='gcash' AND payment_status IN ('unpaid','pending') AND status='Pending' AND created_at<DATE_SUB(NOW(),INTERVAL 24 HOUR)");foreach($q as $o){try{$pdo->beginTransaction();$x=$pdo->prepare('SELECT * FROM order_headers WHERE id=? FOR UPDATE');$x->execute([$o['id']]);$h=$x->fetch();restore_reservations($pdo,(int)$o['id']);$pdo->prepare("UPDATE order_headers SET status='Cancelled',cancellation_reason='GCash payment expired',cancelled_at=NOW() WHERE id=?")->execute([$o['id']]);$legacy=$h['order_type']==='ai'?'ai_cake_orders':'orders';$lid=$h['order_type']==='ai'?$h['ai_order_id']:$h['normal_order_id'];$pdo->prepare("UPDATE {$legacy} SET status='cancelled' WHERE id=?")->execute([$lid]);$pdo->prepare("INSERT INTO order_status_history(order_header_id,from_status,to_status,note) VALUES(?,'Pending','Cancelled','GCash payment expired')")->execute([$o['id']]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,$e->getMessage()."\n");}}echo "Expiry check completed.\n";
